def hosted_text(language, key, **values):
    catalog = HOSTED_TRANSLATIONS.get(language, HOSTED_TRANSLATIONS["en"])
    template = catalog.get(key, HOSTED_TRANSLATIONS["en"].get(key, key))
    return template.format(**values) if values else template
